export const fmtMoney = (minor: number, currency: string, locale: Locale) => {
  const d = ['KWD', 'BHD', 'OMR'].includes(currency) ? 3 : currency === 'JPY' ? 0 : 2; const neg = minor < 0; const abs = Math.abs(minor);
  const s = new Intl.NumberFormat(locale === 'ar' ? 'ar-EG' : 'en-US', { minimumFractionDigits: d, maximumFractionDigits: d }).format(abs / 10 ** d);
  return `${neg ? '-' : ''}${s} ${currency}`;
};
